{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Melagatran, a highly transferable polar thrombin inhibitor, has human oral bioavailability of only 3–7%, directly supporting low F for the query's polar heteroaromatic/piperidine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "The commercial product INVIRASE (saquinavir) has an average absolute oral bioavailability of 4% in humans, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Olcegepant has absolute oral bioavailability <1% in humans, the lowest direct human F among the analogues, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "FK3453, an amino-heteroaromatic drug candidate, showed unexpectedly poor human oral bioavailability due to AO-mediated clearance, supporting low F for the query's aminopyrimidine-like core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Danavorexton had poor oral bioavailability in humans and required IV infusion, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "DX-9065a had absolute human oral bioavailability of only 2–3%, attributed to strongly basic amidino groups; the query's polar heteroaromatic amine is consistent with low F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues with direct human oral bioavailability data show low F (mostly <10%), and none affirm F>=20%. The query's polar aminopyrazolopyrimidine and acrylamide-piperidine features align with poor permeability/first-pass metabolism. Therefore predict low oral bioavailability at the F>=20% threshold.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability value for the query molecule itself; prediction relies on analogue transfer.",
    "Several high-transfer analogues are structurally distant (nucleotides, peptidomimetics), though their consistently low F supports the same direction.",
    "Didanosine shows borderline F near 20% under fasting conditions, but fed values are below threshold and its scaffold is less relevant."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

